use crate::aap::caps::kb_read;

/// Upper bound on the output question, in bytes. A byte bound of 512 also
/// bounds the character count to at most 512.
const MAX_QUESTION_BYTES: usize = 512;

struct Node;

/// Truncates `question` to at most `MAX_QUESTION_BYTES` bytes, cutting only on
/// a character boundary so the result is always valid UTF-8. Under the node's
/// `requires` clause this is the identity; it keeps the `ensures` clause true
/// regardless.
fn bound_question(question: String) -> String {
    if question.len() <= MAX_QUESTION_BYTES {
        return question;
    }
    let mut cut = 0;
    for (i, c) in question.char_indices() {
        let end = i + c.len_utf8();
        if end > MAX_QUESTION_BYTES {
            break;
        }
        cut = end;
    }
    let mut question = question;
    question.truncate(cut);
    question
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let intent = query.query.intent;
        let question = bound_question(query.query.question);
        let knowledge: Vec<String> = kb_read::lookup(&question);
        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

